const cfg = $input.first().json;
const runAt = new Date().toISOString();
const prompts = String(cfg.prompts || '')
  .split('\n')
  .map(p => p.trim())
  .filter(p => p.length > 0);
if (prompts.length === 0) {
  throw new Error('Aucune question : renseigne au moins une ligne dans le champ prompts de la Configuration.');
}
return prompts.map(prompt => ({
  json: { run_id: runAt, run_at: runAt, brand: cfg.brand, prompt: prompt }
}));

const cfg = $('Configuration').first().json;
const NL = String.fromCharCode(10);

function stripMarks(s) {
  const d = String(s || '').normalize('NFD');
  let out = '';
  for (let i = 0; i < d.length; i++) {
    const code = d.charCodeAt(i);
    if (code < 768 || code > 879) out += d.charAt(i);
  }
  return out;
}
function norm(s) {
  return stripMarks(s).toLowerCase();
}
function isWordChar(ch) {
  return /[A-Za-z0-9]/.test(ch);
}
function splitList(s) {
  return String(s || '').split(',').map(function (x) { return x.trim(); }).filter(function (x) { return x.length > 0; });
}
function cleanDomain(d) {
  let s = norm(d).trim();
  const p = s.indexOf('://');
  if (p >= 0) s = s.slice(p + 3);
  if (s.indexOf('www.') === 0) s = s.slice(4);
  const slash = s.indexOf('/');
  if (slash >= 0) s = s.slice(0, slash);
  return s;
}
function firstMention(text, alias) {
  const a = String(alias || '').trim();
  if (!a || !text) return -1;
  const exactCase = a.replace(/[^A-Za-z0-9]/g, '').length <= 4;
  const t = exactCase ? stripMarks(text) : norm(text);
  const n = exactCase ? stripMarks(a) : norm(a);
  let from = 0;
  while (from <= t.length) {
    const i = t.indexOf(n, from);
    if (i < 0) return -1;
    const before = i > 0 ? t.charAt(i - 1) : '';
    const after = t.charAt(i + n.length);
    if (!(before && isWordChar(before)) && !(after && isWordChar(after))) return i;
    from = i + 1;
  }
  return -1;
}
function parseCompetitors(s) {
  const text = String(s || '');
  if (text.indexOf('|') < 0 && text.indexOf(NL) < 0) {
    return splitList(text).map(function (name) { return { name: name, aliases: [name], domains: [] }; });
  }
  return text.split(NL).map(function (l) { return l.trim(); }).filter(function (l) { return l.length > 0; }).map(function (line) {
    const parts = line.split('|').map(function (x) { return x.trim(); });
    return {
      name: parts[0],
      aliases: [parts[0]].concat(splitList(parts[2])),
      domains: splitList(parts[1]).map(cleanDomain).filter(function (d) { return d.length > 0; })
    };
  });
}
function errorText(raw) {
  if (!raw || typeof raw !== 'object') return 'Aucune réponse';
  if (typeof raw.error === 'string') return raw.error;
  if (raw.error && raw.error.message) return String(raw.error.message);
  if (raw.stop_reason === 'refusal') return 'Refus du modèle';
  if (raw.prompt && !raw.output && !raw.candidates && !raw.content) return 'Moteur désactivé ou sans réponse';
  return '';
}
function fromResponsesApi(raw) {
  let answer = typeof raw.output_text === 'string' ? raw.output_text : '';
  const cited = [];
  const searched = [];
  const blocks = Array.isArray(raw.output) ? raw.output : [];
  for (const block of blocks) {
    if (block && block.type === 'message' && Array.isArray(block.content)) {
      for (const part of block.content) {
        if (part && part.type === 'output_text') {
          if (!raw.output_text) answer += (answer ? NL : '') + (part.text || '');
          for (const a of (part.annotations || [])) {
            if (a && a.url) cited.push({ url: a.url, title: a.title || '' });
          }
        }
      }
    }
    if (block && block.type === 'web_search_call' && block.action && Array.isArray(block.action.sources)) {
      for (const s of block.action.sources) searched.push({ url: s.url || '', title: s.title || '' });
    }
    if (block && block.type === 'search_results' && Array.isArray(block.results)) {
      for (const s of block.results) searched.push({ url: s.url || '', title: s.title || '' });
    }
  }
  return { answer: answer, sources: cited.concat(searched) };
}
function fromGemini(raw) {
  const cand = Array.isArray(raw.candidates) && raw.candidates[0] ? raw.candidates[0] : {};
  const parts = (cand.content && cand.content.parts) || (raw.content && raw.content.parts) || [];
  const answer = parts.map(function (p) { return (p && p.text) || ''; }).join('') || (typeof raw.text === 'string' ? raw.text : '');
  const meta = cand.groundingMetadata || raw.groundingMetadata || {};
  const sources = (meta.groundingChunks || []).map(function (c) {
    return { url: (c && c.web && c.web.uri) || '', title: (c && c.web && c.web.title) || '' };
  });
  return { answer: answer, sources: sources };
}
function fromAnthropic(raw) {
  const blocks = Array.isArray(raw.content) ? raw.content : [];
  let answer = '';
  const cited = [];
  const searched = [];
  for (const block of blocks) {
    if (block && block.type === 'text') {
      answer += block.text || '';
      for (const c of (block.citations || [])) {
        if (c && c.url) cited.push({ url: c.url, title: c.title || '' });
      }
    }
    if (block && block.type === 'web_search_tool_result' && Array.isArray(block.content)) {
      for (const r of block.content) {
        if (r && r.url) searched.push({ url: r.url, title: r.title || '' });
      }
    }
  }
  return { answer: answer, sources: cited.concat(searched) };
}
function deepCollect(value, texts, links, depth) {
  if (!value || depth > 8) return;
  if (Array.isArray(value)) {
    for (const v of value) deepCollect(v, texts, links, depth + 1);
    return;
  }
  if (typeof value !== 'object') return;
  if (typeof value.text === 'string' && value.text.length > 30) texts.push(value.text);
  if (typeof value.url === 'string') links.push({ url: value.url, title: value.title || '' });
  if (typeof value.uri === 'string') links.push({ url: value.uri, title: value.title || '' });
  for (const key of Object.keys(value)) {
    if (value[key] && typeof value[key] === 'object') deepCollect(value[key], texts, links, depth + 1);
  }
}
function dedupe(sources) {
  const seen = {};
  const out = [];
  for (const s of sources) {
    const key = String(s.url || s.title || '').toLowerCase();
    if (!key || seen[key]) continue;
    seen[key] = true;
    out.push(s);
  }
  return out;
}
function cut(s, max) {
  const t = String(s || '');
  return t.length > max ? t.slice(0, max - 3) + '...' : t;
}

const tracked = {
  name: String(cfg.brand || '').trim(),
  aliases: [String(cfg.brand || '').trim()].concat(splitList(cfg.aliases)).filter(function (x) { return x.length > 0; }),
  domains: splitList(cfg.domains).map(cleanDomain).filter(function (d) { return d.length > 0; })
};
const brands = [tracked].concat(parseCompetitors(cfg.competitors));

return $input.all().map(function (item) {
  const it = item.json || {};
  const raw = it.raw || {};
  const failure = errorText(raw);
  let parsed = it.engine === 'Gemini' ? fromGemini(raw) : (it.engine === 'Claude' ? fromAnthropic(raw) : fromResponsesApi(raw));
  if (!failure && !parsed.answer) {
    const texts = [];
    const links = [];
    deepCollect(raw, texts, links, 0);
    parsed = { answer: texts.join(NL), sources: parsed.sources.length ? parsed.sources : links };
  }
  const answer = parsed.answer || '';
  const sources = dedupe(parsed.sources);
  const detail = brands.map(function (b) {
    let index = -1;
    b.aliases.forEach(function (a) {
      const i = firstMention(answer, a);
      if (i >= 0 && (index < 0 || i < index)) index = i;
    });
    let rank = 0;
    for (let k = 0; k < sources.length; k++) {
      const hay = norm(sources[k].url) + ' ' + norm(sources[k].title);
      if (b.domains.some(function (d) { return hay.indexOf(d) >= 0; })) {
        rank = k + 1;
        break;
      }
    }
    return { name: b.name, index: index, rank: rank };
  });
  const order = detail.filter(function (d) { return d.index >= 0; }).sort(function (x, y) { return x.index - y.index; });
  const own = detail[0];
  const emptyReason = raw.stop_reason === 'pause_turn' ? 'Recherche interrompue avant la réponse' : 'Réponse vide';
  return {
    json: {
      run_id: it.run_id,
      run_at: it.run_at,
      brand: tracked.name,
      engine: it.engine,
      prompt: it.prompt,
      mentioned: own.index >= 0,
      cited: own.rank > 0,
      citation_rank: own.rank,
      brand_position: order.indexOf(own) + 1,
      mention_order: order.map(function (d, k) { return (k + 1) + '. ' + d.name; }).join(' · '),
      brands_detail: detail.map(function (d) {
        const p = order.indexOf(d) + 1;
        return d.name + ' : ' + (p ? 'citée en position ' + p : 'non citée') + (d.rank ? ', source n°' + d.rank : ', absente des sources');
      }).join(NL),
      competitors_mentioned: order.filter(function (d) { return d !== own; }).map(function (d) { return d.name; }).join(', '),
      answer_excerpt: answer.slice(0, 600),
      answer_long: cut(answer, 1900),
      sources: sources.slice(0, 10).map(function (s) { return (s.title ? s.title + ' | ' : '') + s.url; }).join(NL),
      sources_short: cut(sources.slice(0, 8).map(function (s) { return s.url; }).join(NL), 1900),
      error: failure || (answer ? '' : emptyReason)
    }
  };
});

const current = $('Analyser les réponses').all().map(i => i.json);
const runId = current.length ? current[0].run_id : '';
const history = $input.all().map(i => i.json || {}).filter(r => r.run_id && r.run_id !== runId);
const last = {};
for (const r of history) {
  const key = r.engine + '||' + r.prompt;
  const t = new Date(r.run_at).getTime() || 0;
  if (!last[key] || t > last[key].t) last[key] = { t: t, row: r };
}
function yes(v) {
  return v === true || v === 'true' || v === 1;
}
return current.map(c => {
  const prev = last[c.engine + '||' + c.prompt];
  const visible = c.mentioned || c.cited;
  let status;
  if (c.error) {
    status = 'erreur';
  } else if (!prev || prev.row.error) {
    status = visible ? 'visible' : 'absent';
  } else {
    const wasVisible = yes(prev.row.mentioned) || yes(prev.row.cited);
    if (visible && !wasVisible) status = 'apparu';
    else if (!visible && wasVisible) status = 'disparu';
    else status = visible ? 'visible' : 'absent';
  }
  return { json: Object.assign({}, c, { status: status }) };
});
